  688 linhas de quadro em 55 editais. Nunca toca no 114/2026.

  O que faz (uma transação): confere a conta do setor; para cada edital, confere que ainda não há
  quadro ativo, grava pela mesma função da tela (public.salvar_quadro_de_vagas, origem PDF, nome do
  arquivo do Anexo II) e reprova se o número de linhas ou a soma das vagas imediatas não baterem com
  o Anexo II. Modalidades com os nomes do cabeçalho do edital ("Ampla Concorrência", "PcD", "Pretos e
  Pardos", "Indígenas", "Quilombolas"); null = só cadastro reserva, como a leitura da tela.

  Assinada pela conta do setor (a01afddb-f64b-47d9-80e8-476a1ed14e43). Rode SÓ COM A AUTORIZAÇÃO do usuário, e o ensaio antes.
  Depois de aplicar, registre:
    npm run db:estado -- --registrar=correcoes/20261105-quadros-de-vagas.sql
  Para desfazer: update TB_QUADRO_VAGA_EDITAL set ST_REGISTRO_ATIVO='N' nas linhas gravadas por esta correção.
*/
begin;

-- >>> correcao
set local lock_timeout = '3s';

-- A autoria desta transação: auth.uid() = conta do setor.
select set_config('request.jwt.claims',
  '{"sub":"a01afddb-f64b-47d9-80e8-476a1ed14e43","role":"authenticated","email":"dados.recursoshumanos@agenciasus.org.br"}', true);

do $$
begin
  if not exists (select 1 from public."TB_PERFIL_USUARIO" p
                   join public."TB_GRUPO_ACESSO" a on a."CO_GRUPO_ACESSO" = p.perfil
                  where p.user_id = 'a01afddb-f64b-47d9-80e8-476a1ed14e43' and p.ativo is true and a."ST_ADMIN_GLOBAL") then
    raise exception 'A conta do setor (a01afddb-…) não é administrador global ativo.';
  end if;
  if auth.uid() is distinct from 'a01afddb-f64b-47d9-80e8-476a1ed14e43'::uuid then
    raise exception 'auth.uid() desta transação não é a conta do setor.';
  end if;
end;
$$;

create function pg_temp.cadastrar_quadro(p_id uuid, p_edital text, p_soma int, p_linhas int, p_dados jsonb)
returns void language plpgsql as $f$
declare
  v_soma int;
  v_n int;
begin
  perform 1 from public."TB_MONITORAMENTO_INDIGENA" where id = p_id and edital = p_edital and edital <> '114/2026' for update;
  if not found then raise exception 'Edital % (%) não encontrado (ou é o 114/2026, congelado).', p_edital, p_id; end if;
  if exists (select 1 from public."TB_QUADRO_VAGA_EDITAL" where "CO_MONITORAMENTO" = p_id and "ST_REGISTRO_ATIVO" = 'S') then
    raise exception 'Edital %: já tem quadro de vagas ativo — não substituo.', p_edital;
  end if;
  if jsonb_array_length(p_dados -> 'linhas') <> p_linhas
     or (select sum(coalesce((l ->> 'vagas_imediatas')::int, 0)) from jsonb_array_elements(p_dados -> 'linhas') l) <> p_soma then
    raise exception 'Edital %: o quadro montado não confere com o Anexo II.', p_edital;
  end if;

  perform public.salvar_quadro_de_vagas(p_id, p_dados);

  select count(*), coalesce(sum("QT_VAGA_IMEDIATA"), 0) into v_n, v_soma
    from public."TB_QUADRO_VAGA_EDITAL" where "CO_MONITORAMENTO" = p_id and "ST_REGISTRO_ATIVO" = 'S';
  if v_n <> p_linhas or v_soma <> p_soma then
    raise exception 'Edital %: gravou % linhas e % vagas; o Anexo II tem % linhas e % vagas.', p_edital, v_n, v_soma, p_linhas, p_soma;
  end if;
end;
$f$;

